<?php

namespace App;

use App\Models\User;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Str;

/**
 * A reseller API key. Not a CMS model — `api_keys` is a plain migration table,
 * so nothing here is regenerated by a CMS page save.
 *
 * The key itself is never stored: only its sha256, which is all a lookup needs
 * (a key is 40 random characters, so a fast hash is enough — there is nothing to
 * brute-force the way there is with a human password).
 */
class ApiKey extends Model
{
    public const PREFIX = 'bc_live_';

    protected $fillable = ['user_id', 'name', 'prefix', 'key_hash', 'allowed_ips'];

    protected $hidden = ['key_hash'];

    protected $casts = [
        'allowed_ips' => 'array',
        'last_used_at' => 'datetime',
        'revoked_at' => 'datetime',
    ];

    public function user()
    {
        return $this->belongsTo(User::class);
    }

    /**
     * Create a key for `$user`. Returns [ApiKey, plaintext] — the plaintext is
     * shown to the user once and is unrecoverable afterwards.
     */
    public static function issue(User $user, string $name, ?array $allowedIps = null): array
    {
        $plain = self::PREFIX . Str::random(40);

        $key = self::create([
            'user_id' => $user->id,
            'name' => $name,
            'prefix' => substr($plain, 0, strlen(self::PREFIX) + 4),
            'key_hash' => self::hash($plain),
            'allowed_ips' => $allowedIps ?: null,
        ]);

        return [$key, $plain];
    }

    public static function hash(string $plain): string
    {
        return hash('sha256', $plain);
    }

    public static function findActive(string $plain): ?self
    {
        return self::whereNull('revoked_at')
            ->where('key_hash', self::hash($plain))
            ->first();
    }

    public function allowsIp(?string $ip): bool
    {
        $allowed = array_filter((array) $this->allowed_ips);

        return $allowed === [] || in_array($ip, $allowed, true);
    }
}
